theme.css:
/* theme: Steady Pulse | A market holding its breath before the Fed, calm metals and measured numbers — a page of quiet confidence and disciplined warmth. */
/* layout: hero=classic; political-news=plain/stack; financial-news=stat/feature; entertainment-news=tile/grid-2; music-releases=numbered/grid-2; stock-analysis=stat/grid-3; outlook=outline/stack */

.diary-page {
  --paper: #f9f5f0;
  --paper-alt: #f2ebe1;
  --ink: #1d1a17;
  --ink-soft: #3f3a33;
  --muted: #6b6357;
  --accent: #7a4f22;
  --accent-ink: #f9f5f0;
  --rule: #d9d0c4;
  --font-display: var(--ff-fraunces), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
  --accent-soft: #a67c3d;
}

.diary-page {
  background: var(--paper);
  color: var(--ink-soft);
}

.diary-page .diary-hero {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
  position: relative;
}

.diary-page .diary-hero::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 3px;
  background: linear-gradient(90deg, var(--accent) 0%, var(--accent) 30%, var(--rule) 30%, var(--rule) 70%, var(--accent) 70%, var(--accent) 100%);
}

.diary-page .diary-hero-inner {
  padding-block: 3rem 4rem;
  max-width: 84rem;
}

.diary-page .diary-kicker {
  color: var(--accent);
  font-size: 0.7rem;
  letter-spacing: 0.28em;
  margin-top: 3rem;
}

.diary-page .diary-title {
  font-size: clamp(2.75rem, 7vw, 5.5rem);
  font-weight: 400;
  letter-spacing: -0.03em;
  line-height: 1.04;
  max-width: 24ch;
  color: var(--ink);
}

.diary-page .diary-summary {
  font-size: clamp(1.2rem, 2.2vw, 1.5rem);
  line-height: 1.6;
  color: var(--ink-soft);
  max-width: 50rem;
}

.diary-page .diary-theme-note {
  color: var(--muted);
  font-size: 0.82rem;
}

.diary-page .diary-theme-name {
  background: var(--accent-soft);
  color: var(--ink);
  border-radius: 0;
  padding: 0.2rem 0.7rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-size: 0.72rem;
  border: 1px solid var(--accent);
}

.diary-page .diary-crumbs a {
  color: var(--muted);
  font-size: 0.8rem;
}

.diary-page .diary-crumbs a:hover {
  color: var(--accent);
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top {
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-label {
    color: var(--muted);
    letter-spacing: 0.2em;
  }

  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }

  .diary-page .diary-toc-link {
    border-left-color: transparent;
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

.diary-page .diary-article {
  container: article / inline-size;
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  padding-block: 3.5rem;
}

.diary-page .diary-section:first-child {
  border-top: 0;
}

.diary-page .diary-section-head {
  margin-bottom: 2.25rem;
}

.diary-page .diary-section-number {
  font-size: 0.7rem;
  letter-spacing: 0.22em;
  color: var(--accent);
  font-weight: 600;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3.25rem);
  font-weight: 400;
  letter-spacing: -0.02em;
  color: var(--ink);
  line-height: 1.1;
}

.diary-page .diary-prose {
  font-size: 1.18rem;
  line-height: 1.8;
  color: var(--ink-soft);
}

.diary-page .diary-prose > * + * {
  margin-top: 1.2em;
}

.diary-page .diary-prose h3 {
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: 1.45rem;
  color: var(--ink);
  letter-spacing: -0.01em;
  margin-top: 2.2em;
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid color-mix(in srgb, var(--accent) 60%, transparent);
  font-size: 0.62em;
  letter-spacing: 0.1em;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
  border-color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  font-style: italic;
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose hr {
  border-color: var(--rule);
}

.diary-page .diary-card {
  container-type: inline-size;
}

.diary-page .diary-card-inner {
  gap: 1rem;
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.25;
  color: var(--ink);
}

.diary-page .diary-card-body {
  font-size: 1.08rem;
  line-height: 1.75;
}

.diary-page .diary-card-thread {
  border: 1px solid var(--accent);
  border-radius: 0;
  color: var(--accent);
  background: var(--paper);
  font-size: 0.72rem;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page [data-card="plain"] .diary-card-inner {
  padding-block: 1rem;
}

.diary-page [data-section="political-news"] [data-card="plain"]:not(:first-child) {
  border-top: 1px solid var(--rule);
  padding-top: 2.5rem;
}

.diary-page [data-card="elevated"] .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
  box-shadow: 0 1px 2px rgb(29 26 23 / 0.04), 0 8px 24px -12px rgb(29 26 23 / 0.1);
  padding: 1.75rem;
}

.diary-page [data-card="outline"] .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: 2rem;
}

.diary-page [data-card="outline"] .diary-card-title {
  font-size: 1.3rem;
}

.diary-page [data-card="tile"] .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: 2rem;
  position: relative;
}

.diary-page [data-card="tile"] .diary-card-inner::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: linear-gradient(90deg, var(--accent), var(--accent) 40%, var(--rule) 40%, var(--rule) 100%);
}

.diary-page [data-card="tile"] .diary-card-title {
  font-size: 1.35rem;
  font-weight: 500;
}

.diary-page [data-card="numbered"] .diary-card-index {
  font-family: var(--font-display);
  font-size: 2.75rem;
  font-weight: 400;
  line-height: 0.9;
  color: var(--accent);
}

.diary-page [data-card="numbered"] .diary-card-inner {
  grid-template-columns: auto 1fr;
}

.diary-page [data-card="numbered"] .diary-card-index::after {
  content: ".";
  color: var(--ink);
}

.diary-page [data-card="lede"] {
  border-top: 3px solid var(--accent);
  padding-top: 1.25rem;
}

.diary-page .diary-card-lede {
  padding-left: 0;
  border-left: 0;
  border-bottom: 1px solid var(--rule);
  padding-bottom: 1rem;
  margin-bottom: 0.5rem;
  font-family: var(--font-display);
  font-size: 1.4rem;
  line-height: 1.4;
  color: var(--ink);
}

.diary-page [data-card="stat"] {
  border-top: 3px solid var(--accent);
  padding-top: 1.25rem;
}

.diary-page .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 14cqi, 4rem);
  font-weight: 400;
  letter-spacing: -0.03em;
  line-height: 1;
  color: var(--accent);
}

.diary-page .diary-card-figure::after {
  content: "";
  display: block;
  width: 100%;
  height: 1px;
  background: var(--rule);
  margin-top: 1rem;
}

.diary-page [data-card="timeline"] {
  position: relative;
}

.diary-page [data-card="timeline"] .diary-card-inner {
  padding-left: 2.25rem;
}

.diary-page [data-card="timeline"] .diary-card-inner::before {
  content: "";
  position: absolute;
  left: 0.5rem;
  top: 0.2rem;
  bottom: -1rem;
  width: 1px;
  background: var(--rule);
}

.diary-page [data-card="timeline"]:last-child .diary-card-inner::before {
  bottom: 0;
}

.diary-page [data-card="timeline"] .diary-card-inner::after {
  content: "";
  position: absolute;
  left: 0;
  top: 0.5rem;
  width: 1rem;
  height: 1rem;
  border: 2px solid var(--accent);
  border-radius: 50%;
  background: var(--paper);
  box-shadow: none;
}

.diary-page [data-card="banner"] .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  overflow: hidden;
  gap: 0;
}

.diary-page [data-card="banner"] .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  padding: 1rem 1.5rem;
  font-size: 1.2rem;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.diary-page [data-card="banner"] .diary-card-body {
  padding: 1.5rem;
}

.diary-page [data-card="split"] .diary-card-inner {
  padding-top: 1.5rem;
  border-top: 2px solid var(--ink);
}

.diary-page [data-card="split"] .diary-card-title {
  font-size: 1.35rem;
}

.diary-page .diary-stories--stack {
  max-width: 52rem;
  gap: 2.5rem;
}

.diary-page .diary-stories--grid-2,
.diary-page .diary-stories--grid-3 {
  gap: 2rem;
}

.diary-page .diary-stories--grid-2 > .diary-card,
.diary-page .diary-stories--grid-3 > .diary-card,
.diary-page .diary-stories--feature > .diary-card {
  min-width: 0;
}

.diary-page .diary-stories--masonry {
  columns: 2 20rem;
  column-gap: 2rem;
}

.diary-page .diary-stories--masonry > .diary-card {
  margin-bottom: 2rem;
  break-inside: avoid;
}

.diary-page .diary-stories--rail {
  grid-auto-flow: column;
  grid-auto-columns: minmax(16rem, 85%);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
}

.diary-page .diary-stories--rail > .diary-card {
  scroll-snap-align: start;
}

@media (min-width: 40rem) {
  .diary-page .diary-stories--grid-2,
  .diary-page .diary-stories--grid-3,
  .diary-page .diary-stories--feature {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .diary-page .diary-stories--feature > .diary-card:first-child {
    grid-column: 1 / -1;
  }

  .diary-page .diary-stories--rail {
    grid-auto-columns: minmax(17rem, 42%);
  }
}

@media (min-width: 54rem) {
  .diary-page .diary-stories--grid-3 {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.diary-page .diary-markets-label {
  color: var(--muted);
  font-size: 0.7rem;
  letter-spacing: 0.18em;
}

.diary-page .diary-markets {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  padding: 1.5rem;
  gap: 0;
}

.diary-page .diary-spark {
  background: var(--paper);
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: 0.9rem;
}

.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark-value {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-spark-change.is-up {
  color: #3b7554;
}

.diary-page .diary-spark-change.is-down {
  color: var(--accent);
}

.diary-page .diary-footer {
  border-top-color: var(--rule);
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 0.78rem;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

.diary-page .diary-footer-prev::before {
  content: "← ";
}

.diary-page .diary-footer-next::after {
  content: " →";
}

.diary-page .diary-section[data-section="political-news"] .diary-prose h3 {
  color: var(--accent);
  font-size: 0.7rem;
  letter-spacing: 0.24em;
}

.diary-page .diary-section[data-section="political-news"] .diary-prose h3 + p {
  margin-top: 0.4em;
}

.diary-page .diary-section[data-section="political-news"] .diary-prose h3 {
  border-top: 1px solid var(--rule);
  padding-top: 1.75rem;
  margin-top: 2.25rem;
  font-weight: 600;
}

.diary-page .diary-section[data-section="political-news"] .diary-prose > h3:first-child {
  border-top: 0;
  padding-top: 0;
  margin-top: 0;
}

.diary-page .diary-section[data-section="political-news"] .diary-prose .diary-card-body {
  font-size: 1.2rem;
}

.diary-page .diary-section[data-section="financial-news"] {
  border-top: 3px solid var(--ink);
}

.diary-page .diary-section[data-section="financial-news"] .diary-stories--feature > .diary-card:first-child .diary-card-inner {
  border: 1px solid var(--rule);
  padding: 2.5rem;
  background: var(--paper-alt);
  position: relative;
}

.diary-page .diary-section[data-section="financial-news"] .diary-stories--feature > .diary-card:first-child .diary-card-inner::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 4px;
  background: var(--accent);
}

.diary-page .diary-section[data-section="financial-news"] .diary-stories--feature > .diary-card:first-child .diary-card-title {
  font-size: 2rem;
  margin-bottom: 0.75rem;
}

.diary-page .diary-section[data-section="financial-news"] .diary-stories--feature > .diary-card:first-child .diary-card-body {
  font-size: 1.15rem;
}

.diary-page .diary-section[data-section="financial-news"] .diary-stories--feature > .diary-card:not(:first-child) {
  border-top: 2px solid var(--rule);
  padding-top: 2rem;
}

.diary-page .diary-section[data-section="financial-news"] .diary-stories--feature > .diary-card:not(:first-child) .diary-card-inner {
  gap: 0.5rem;
}

.diary-page .diary-section[data-section="financial-news"] .diary-stories--feature > .diary-card:not(:first-child) .diary-card-title {
  font-size: 1.2rem;
}

.diary-page .diary-section[data-section="entertainment-news"] .diary-prose h4 {
  font-size: 1.3rem;
  margin-top: 1.5em;
  border-bottom: 1px solid var(--rule);
  padding-bottom: 0.4rem;
  margin-bottom: 0.25rem;
}

.diary-page .diary-section[data-section="entertainment-news"] .diary-prose h4:first-child {
  margin-top: 0;
}

.diary-page .diary-section[data-section="entertainment-news"] .diary-prose > p {
  font-size: 1.08rem;
}

.diary-page .diary-section[data-section="entertainment-news"] .diary-prose h4 + p {
  margin-top: 0.6em;
}

.diary-page .diary-section[data-section="music-releases"] .diary-prose ul > li {
  padding-left: 0;
  position: relative;
  padding-bottom: 1.1rem;
  border-bottom: 1px solid var(--rule);
  margin-bottom: 1.1rem;
}

.diary-page .diary-section[data-section="music-releases"] .diary-prose ul > li::before {
  content: none;
}

.diary-page .diary-section[data-section="music-releases"] .diary-prose ul > li strong {
  display: block;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: 1.2rem;
  color: var(--ink);
  margin-bottom: 0.25rem;
}

.diary-page .diary-section[data-section="music-releases"] .diary-prose ul > li:last-child {
  border-bottom: 0;
}

.diary-page .diary-section[data-section="music-releases"] .diary-prose .diary-card-body {
  font-size: 1rem;
}

.diary-page .diary-section[data-section="music-releases"] .diary-card-body {
  background: var(--paper);
}

.diary-page .diary-section[data-section="music-releases"] .diary-embed {
  border-radius: 2px;
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page .diary-section[data-section="music-releases"] .diary-card--numbered .diary-card-inner {
  background: var(--paper);
  padding: 1.5rem 1.5rem 0.5rem;
  border: 1px solid var(--rule);
  border-top: 0;
}

.diary-page [data-section="music-releases"] .diary-card-index {
  font-family: var(--font-display);
  font-size: 2.25rem;
  font-weight: 400;
  color: var(--accent);
}

.diary-page .diary-section[data-section="music-releases"] .diary-card--numbered .diary-card-title {
  font-size: 1.2rem;
  line-height: 1.35;
}

.diary-page .diary-section[data-section="stock-analysis"] .diary-prose h4 {
  font-family: var(--font-ui);
  font-weight: 600;
  font-size: 0.76rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent);
  margin-top: 0;
}

.diary-page .diary-section[data-section="stock-analysis"] .diary-prose .diary-card-body {
  font-size: 1.02rem;
}

.diary-page .diary-section[data-section="stock-analysis"] .diary-card--stat .diary-card-figure {
  font-size: clamp(2rem, 12cqi, 3.5rem);
}

.diary-page .diary-section[data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  border-top: 3px solid var(--rule);
  padding-top: 1.25rem;
}

.diary-page .diary-section[data-section="stock-analysis"] .diary-card--stat .diary-card-title {
  font-size: 1.15rem;
  font-weight: 500;
  letter-spacing: -0.01em;
}

.diary-page .diary-section[data-section="stock-analysis"] .diary-card-figure::after {
  background: var(--rule);
  width: 40%;
  margin-top: 0.75rem;
}

.diary-page .diary-section[data-section="stock-analysis"] .diary-card--outline .diary-card-inner {
  border: 0;
  border-top: 1px solid var(--rule);
  padding: 1rem 0 0;
}

.diary-page .diary-section[data-section="stock-analysis"] .diary-card--outline .diary-card-title {
  font-size: 1.1rem;
}

.diary-page .diary-section[data-section="stock-analysis"] .diary-card--outline .diary-card-figure {
  font-size: 2.25rem;
  margin-top: 0.25rem;
}

.diary-page .diary-section[data-section="outlook"] {
  border-top: 3px solid var(--ink);
}

.diary-page .diary-section[data-section="outlook"] .diary-stories--stack {
  max-width: 60rem;
}

.diary-page .diary-section[data-section="outlook"] .diary-card--outline .diary-card-inner {
  padding: 2.5rem;
  border-left: 4px solid var(--accent);
  background: var(--paper-alt);
  border-top: 1px solid var(--rule);
  border-right: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-section[data-section="outlook"] .diary-card-title {
  font-size: 1.65rem;
  margin-bottom: 0.5rem;
}

.diary-page .diary-section[data-section="outlook"] .diary-prose h4 {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: 1.2rem;
  text-transform: none;
  letter-spacing: -0.01em;
  color: var(--ink);
  border-bottom: 1px solid var(--rule);
  padding-bottom: 0.4rem;
  padding-left: 1.25rem;
  position: relative;
}

.diary-page .diary-section[data-section="outlook"] .diary-prose h4::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.45em;
  width: 0.6rem;
  height: 0.6rem;
  border: 2px solid var(--accent);
  border-radius: 2px;
  background: var(--paper-alt);
}

.diary-page .diary-section[data-section="outlook"] .diary-prose ul > li {
  padding-left: 0;
}

.diary-page [data-section="outlook"] .diary-prose ul > li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.75em;
  width: 0.5rem;
  height: 2px;
  background: var(--accent);
}

.diary-page .diary-section[data-section="outlook"] .diary-prose ul > li {
  position: relative;
  padding-left: 1.5rem;
}

.diary-page .diary-section[data-section="outlook"] .diary-prose strong {
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-footer-meta::before {
  content: "· ";
  color: var(--accent);
}

.diary-page .diary-prose a {
  white-space: normal !important;
  overflow-wrap: anywhere;
}

.diary-page .diary-prose .diary-card-body > p::first-letter {
